  static string Text(Dictionary<string,object> d,string key){object v;return d.TryGetValue(key,out v)?Convert.ToString(v):"";}
  internal async Task<ActionResult> Command(string op,Dictionary<string,object> args){if(ReadOnly&&op!="Capture"&&op!="Refresh")return ActionResult.Fail("Read-only preview: no server or configuration action was performed.");if(Busy||Lifecycle.StartupPending)return ActionResult.Fail("An operation is already active.");Busy=true;ActionResult result;try{
   if(op=="Start"||op=="Stop"||op=="Restart"){if(op=="Stop")Guard.ManualStop();else Guard.ManualStart();result=await Task.Run(()=>Lifecycle.Execute(op));}
   else if(op=="Backup"){Plan.Begin(Settings.BackupIntervalMinutes,DateTime.UtcNow);result=await Task.Run(()=>SaveBackup.Create(Settings.ServerRoot,Backups,Telemetry.GetHost().ServerRunning));Plan.Finish(result.Success,result.Message,Settings.BackupIntervalMinutes,DateTime.UtcNow);NextBackup=Plan.State.NextUtc;}
