   else if(op=="SaveField"){string path=Path.Combine(Settings.ServerRoot,"enshrouded_server.json"),hash=InstallationAudit.Hash(path);var data=Maintenance.Config(Settings.ServerRoot);var field=ConfigurationDocument.Flatten(data).FirstOrDefault(f=>f.Path==Text(args,"path"));if(field==null||field.Set==null||ConfigurationDocument.ReadOnlyReason(field)!=null||field.Key=="password"||field.Path.StartsWith("bannedAccounts"))throw new IOException("This setting requires the protected editor.");field.Set(ConfigurationDocument.ConvertValue(field,args["value"]));result=await Task.Run(()=>Maintenance.SaveConfiguration(Settings.ServerRoot,js.Serialize(data),hash));}
